/*
 * observe-judge.test.js — the judge-pass flow on Observe (public-lab
 * Requirements 21.6, 21.7, 21.19, 21.20, 21.25, 14.37).
 * Run with `node tests/js/observe-judge.test.js`. Real public/js/observe.js and
 * public/js/api.js, a scripted fake API client, a fake location / history /
 * storage / console that all record. No network. Pass values are generated by a
 * seeded generator; no real pass appears here.
 */
'use strict';

const assert = require('assert');
const path = require('path');
const { createFakeApi } = require('./helpers/fake-api.js');
const { createFakeVoices } = require('./helpers/fake-voices.js');
const { mulberry32, int } = require('./helpers/rng.js');

const ROOT = path.join(__dirname, '..', '..');
const OBSERVE = path.join(ROOT, 'public', 'js', 'observe.js');
const API_JS = path.join(ROOT, 'public', 'js', 'api.js');

const NOTE_TEXT = 'Judge pass active until January 29, 2027, 1:00 PM PT.';
const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_-';
const OLD_ON = ['The lab has had a busy day. It opens again tomorrow (UTC).',
  'You have run the lab many times today. It opens again tomorrow (UTC).'];
const JUDGE_LIMIT = 'The judge pass has been used many times today. It opens again tomorrow (UTC).';

const rng = mulberry32(270227);
function genPass() {
  const n = int(rng, 8, 64);
  let s = '';
  for (let i = 0; i < n; i++) { s += ALPHABET[int(rng, 0, ALPHABET.length - 1)]; }
  return s;
}

// ── DOM shim ────────────────────────────────────────────────────────────────
function makeElement() {
  const attrs = {};
  const classes = new Set();
  const listeners = {};
  let ownText = '';
  const el = {
    children: [], attrs: attrs, hidden: false, disabled: false, style: {}, className: '', _subs: {},
    appendChild: function (c) { el.children.push(c); return c; },
    setAttribute: function (k, v) { attrs[k] = String(v); },
    getAttribute: function (k) { return Object.prototype.hasOwnProperty.call(attrs, k) ? attrs[k] : null; },
    addEventListener: function (ev, fn) { (listeners[ev] = listeners[ev] || []).push(fn); },
    click: function () { (listeners.click || []).forEach(function (fn) { fn(); }); },
    querySelector: function (sel) { return el._subs[sel] || null; },
    classList: {
      add: function (c) { classes.add(c); },
      remove: function (c) { classes.delete(c); },
      contains: function (c) { return classes.has(c); }
    }
  };
  Object.defineProperty(el, 'textContent', {
    get: function () { return el.children.length ? el.children.map(function (c) { return c.textContent; }).join('') : ownText; },
    set: function (v) { ownText = String(v); el.children.length = 0; }
  });
  return el;
}

async function settle() { for (let i = 0; i < 12; i++) { await new Promise(function (r) { setImmediate(r); }); } }

const origConsole = {};
['log', 'info', 'warn', 'error', 'debug'].forEach(function (k) { origConsole[k] = console[k]; });

// Boot a fresh Observe page. opts: { hash, script, noReplaceState }.
// Returns the page record; call page.done() to restore the console.
async function boot(opts) {
  const events = [];          // ordered: 'replaceState' and 'req:<method>'
  const urls = [];            // every URL given to replaceState
  const storageWrites = [];   // every write to either storage
  const consoleCalls = [];    // every console call's arguments
  const byId = {};
  const doc = {
    readyState: 'loading',
    _ready: [],
    addEventListener: function (ev, fn) { if (ev === 'DOMContentLoaded') { doc._ready.push(fn); } },
    createElement: function () { return makeElement(); },
    createTextNode: function (t) { const n = makeElement(); n.textContent = t; return n; },
    getElementById: function (id) {
      if (id.indexOf('log-turn-') === 0) { return null; }
      if (!byId[id]) { byId[id] = makeElement(); }
      return byId[id];
    }
  };
  const loc = { hash: opts.hash || '', pathname: '/index.php', search: '?x=1' };
  const hashAtRequest = [];
  const store = function () {
    return { getItem: function () { return null; }, setItem: function (k, v) { storageWrites.push([k, v]); },
      removeItem: function () {}, clear: function () {} };
  };

  global.document = doc;
  global.window = {};
  global.location = loc;
  if (opts.noReplaceState) {
    global.history = {};
  } else {
    global.history = {
      replaceState: function (state, title, url) {
        events.push('replaceState');
        urls.push(String(url));
        loc.hash = '';
      }
    };
  }
  global.window.localStorage = store();
  global.sessionStorage = store();
  global.window.sessionStorage = global.sessionStorage;
  Object.keys(origConsole).forEach(function (k) {
    console[k] = function () { consoleCalls.push(Array.prototype.slice.call(arguments)); };
  });

  byId['judge-note'] = makeElement();
  byId['judge-note'].hidden = true;
  ['sw-earthquake', 'sw-heat'].forEach(function (id) {
    const b = doc.getElementById(id);
    b._subs['.mark'] = makeElement();
    b.setAttribute('aria-pressed', 'false');
  });
  ['meter-temp', 'meter-water', 'meter-injury', 'meter-fear', 'meter-room'].forEach(function (id) {
    const m = doc.getElementById(id);
    m._subs['.fill'] = makeElement();
    m._subs['.val'] = makeElement();
  });

  const fake = createFakeApi(opts.script || {});
  const proxy = {};
  Object.keys(fake).forEach(function (k) {
    if (typeof fake[k] !== 'function' || k === 'count' || k === 'callsOf') { return; }
    proxy[k] = function () {
      events.push('req:' + k);
      hashAtRequest.push(loc.hash);
      return fake[k].apply(fake, arguments);
    };
  });
  const voices = createFakeVoices(null, { gestured: false });
  global.window.createApiClient = function () { return proxy; };
  global.window.createVoices = function () { return voices; };
  global.window.createHouseRenderer = function () {
    return { mount: function () {}, start: function () {}, setThinking: function () {}, setWorld: function () {}, reset: function () {} };
  };
  global.window.observeWait = function () { return Promise.resolve(); };
  global.window.memoryUi = { renderStatusLine: function () {}, buildConfirmPanel: function () { return makeElement(); } };

  delete require.cache[require.resolve(OBSERVE)];
  require(OBSERVE);
  doc._ready.forEach(function (fn) { fn(); });
  await settle();

  return {
    events: events, urls: urls, storageWrites: storageWrites, consoleCalls: consoleCalls,
    hashAtRequest: hashAtRequest, loc: loc, fake: fake, byId: byId,
    note: byId['judge-note'], ctl: global.window.observeController,
    done: function () { Object.keys(origConsole).forEach(function (k) { console[k] = origConsole[k]; }); }
  };
}

let passed = 0;
async function check(name, fn) {
  await fn();
  passed += 1;
  origConsole.log('  ok - ' + name);
}

function noPassAnywhere(page, pass) {
  const hay = JSON.stringify([page.urls, page.storageWrites, page.consoleCalls, page.loc.search, page.loc.pathname]);
  assert.ok(hay.indexOf(pass) === -1, 'pass leaked into a URL, storage write or console call');
  assert.strictEqual(page.loc.hash, '', 'fragment must be gone');
}

(async function () {
  origConsole.log('observe judge pass');

  await check('fragment removed by replaceState before any request; one POST with the pass; no leak', async function () {
    for (let i = 0; i < 6; i++) {
      const pass = genPass();
      const page = await boot({
        hash: '#judge=' + pass,
        script: { judgePass: { status: 200, body: { ok: true } }, judgeStatus: { status: 200, body: { judge: true } } }
      });
      page.done();
      assert.strictEqual(page.events[0], 'replaceState');
      assert.strictEqual(page.events.indexOf('replaceState'), 0);
      assert.ok(page.events.indexOf('req:judgePass') > 0);
      assert.ok(page.hashAtRequest.every(function (h) { return h === ''; }), 'hash gone at every request');
      assert.deepStrictEqual(page.urls, ['/index.php?x=1']);
      assert.strictEqual(page.fake.count('judgePass'), 1);
      assert.deepStrictEqual(page.fake.callsOf('judgePass')[0].args, [pass]);
      assert.ok(page.events.indexOf('req:judgePass') < page.events.indexOf('req:judgeStatus'));
      noPassAnywhere(page, pass);
    }
  });

  await check('the real client sends the pass in a JSON body {pass}, not in the URL', async function () {
    const seen = [];
    global.fetch = function (url, init) {
      seen.push({ url: url, init: init });
      return Promise.resolve({ status: 200, text: function () { return Promise.resolve('{"ok":true}'); } });
    };
    const pass = genPass();
    const client = require(API_JS).createApiClient();
    await client.judgePass(pass);
    await client.judgeStatus();
    delete global.fetch;
    assert.strictEqual(seen[0].init.method, 'POST');
    assert.deepStrictEqual(JSON.parse(seen[0].init.body), { pass: pass });
    assert.strictEqual(seen[0].init.headers['Content-Type'], 'application/json');
    assert.ok(seen[0].url.indexOf(pass) === -1);
    assert.strictEqual(seen[1].init.method, 'GET');
    assert.strictEqual(seen[1].init.body, undefined);
  });

  await check('without replaceState nothing is sent', async function () {
    const pass = genPass();
    const page = await boot({
      hash: '#judge=' + pass, noReplaceState: true,
      script: { judgePass: { status: 200, body: {} }, judgeStatus: { status: 200, body: { judge: true } } }
    });
    page.done();
    assert.strictEqual(page.fake.count('judgePass'), 0);
    assert.strictEqual(page.fake.count('judgeStatus'), 0);
    assert.strictEqual(page.note.hidden, true);
  });

  await check('a malformed fragment is not a pass: status only, no replaceState', async function () {
    const page = await boot({
      hash: '#judge=' + genPass() + '.bad',
      script: { judgePass: { status: 200, body: {} }, judgeStatus: { status: 200, body: { judge: false } } }
    });
    page.done();
    assert.strictEqual(page.fake.count('judgePass'), 0);
    assert.strictEqual(page.fake.count('judgeStatus'), 1);
    assert.ok(page.events.indexOf('replaceState') === -1);
  });

  await check('no fragment: GET status only; note hidden unless judge is true', async function () {
    const off = await boot({ script: { judgePass: { status: 200, body: {} }, judgeStatus: { status: 200, body: { judge: false } } } });
    off.done();
    assert.strictEqual(off.fake.count('judgePass'), 0);
    assert.strictEqual(off.fake.count('judgeStatus'), 1);
    assert.ok(off.events.indexOf('replaceState') === -1);
    assert.strictEqual(off.note.hidden, true);

    const on = await boot({ script: { judgeStatus: { status: 200, body: { judge: true } } } });
    on.done();
    assert.strictEqual(on.note.hidden, false);
    assert.strictEqual(on.note.textContent, NOTE_TEXT);

    const odd = await boot({ script: { judgeStatus: { status: 200, body: { judge: 'true' } } } });
    odd.done();
    assert.strictEqual(odd.note.hidden, true);
  });

  await check('a fake without the judge calls leaves Observe working as before', async function () {
    const page = await boot({ hash: '#judge=' + genPass(), script: {} });
    page.done();
    assert.strictEqual(page.note.hidden, true);
    assert.strictEqual(page.ctl._state().phase, 'idle');
  });

  await check('403, 404 and network failure show nothing and Observe still loads', async function () {
    const cases = [
      { judgePass: { status: 403, body: { error: 'forbidden' } }, judgeStatus: { status: 403, body: null } },
      { judgePass: { status: 404, body: null }, judgeStatus: { status: 404, body: null } },
      { judgePass: new Error('network'), judgeStatus: new Error('network') },
      { judgePass: { status: 200, body: {} }, judgeStatus: new Error('network') }
    ];
    for (const script of cases) {
      const pass = genPass();
      const page = await boot({ hash: '#judge=' + pass, script: script });
      page.done();
      assert.strictEqual(page.note.hidden, true);
      assert.strictEqual(page.note.textContent, '');
      assert.strictEqual(page.ctl._state().phase, 'idle');
      assert.ok(page.fake.count('memoryStatus') >= 1, 'Observe still loads');
      noPassAnywhere(page, pass);
    }
  });

  await check('daily limits: judge message with both Levers OFF and the stage untouched', async function () {
    const texts = [
      ['daily_judge_limit', JUDGE_LIMIT],
      ['daily_site_limit', OLD_ON[0]],
      ['daily_device_limit', OLD_ON[1]]
    ];
    for (const [code, text] of texts) {
      const page = await boot({ script: { createEpisode: { status: 429, body: { error: code } } } });
      page.done();
      page.byId['sw-earthquake'].click();
      page.byId['btn-start'].click();
      await settle();
      assert.strictEqual(page.byId.notice.textContent, text);
      assert.strictEqual(page.byId.notice.hidden, false);
      assert.strictEqual(page.byId['sw-earthquake']._subs['.mark'].textContent, 'OFF');
      assert.strictEqual(page.byId['sw-heat']._subs['.mark'].textContent, 'OFF');
      const st = page.ctl._state();
      assert.strictEqual(st.phase, 'idle');
      assert.strictEqual(st.episodeId, null);
      assert.strictEqual(page.fake.count('createEpisode'), 1);
      assert.strictEqual(page.fake.count('ask'), 0);
    }
  });

  origConsole.log(passed + ' checks passed');
})().catch(function (e) {
  Object.keys(origConsole).forEach(function (k) { console[k] = origConsole[k]; });
  console.error(e);
  process.exit(1);
});
